## Submitted testbench
```systemverilog
`timescale 1ns / 1ps

module tb;

  localparam int CLK_PERIOD = 8;
  localparam logic [15:0] PRESCALE = 16'd5;
  localparam int BIT_CLKS = int'(PRESCALE) * 8;

  logic        clk = 1'b0;
  logic        rst = 1'b0;
  logic        rxd = 1'b1;
  logic        m_axis_tready = 1'b0;
  logic [7:0]  s_axis_tdata = 8'h00;
  logic        s_axis_tvalid = 1'b0;
  logic [15:0] prescale = PRESCALE;

  wire [7:0] m_axis_tdata;
  wire        m_axis_tvalid;
  wire        s_axis_tready;
  wire        txd;
  wire        tx_busy;
  wire        rx_busy;
  wire        rx_overrun_error;
  wire        rx_frame_error;

  always #(CLK_PERIOD / 2) clk = ~clk;

  uart dut (
    .clk(clk),
    .rst(rst),
    .s_axis_tdata(s_axis_tdata),
    .s_axis_tvalid(s_axis_tvalid),
    .s_axis_tready(s_axis_tready),
    .m_axis_tdata(m_axis_tdata),
    .m_axis_tvalid(m_axis_tvalid),
    .m_axis_tready(m_axis_tready),
    .rxd(rxd),
    .txd(txd),
    .tx_busy(tx_busy),
    .rx_busy(rx_busy),
    .rx_overrun_error(rx_overrun_error),
    .rx_frame_error(rx_frame_error),
    .prescale(prescale)
  );

  task automatic wait_clks(input int n);
    repeat (n) @(negedge clk);
  endtask

  task automatic do_reset();
    rst = 1'b1;
    wait_clks(4);
    rst = 1'b0;
    wait_clks(4);
  endtask

  initial begin
    do_reset();
    m_axis_tready = 1'b0;

    // Frame 1: 0x3C = 8'b00111100, LSB first: 0,0,1,1,1,1,1,0
    // Deliver with m_axis_tready low so the word stalls.
    rxd = 1'b0; wait_clks(BIT_CLKS);  // start
    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[0]
    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[1]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[2]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[3]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[4]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[5]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[6]
    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[7]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // stop

    // m_axis_tvalid is now high with 0x3C, stalled by m_axis_tready=0
    wait_clks(5);

    // Inter-frame gap (rxd already high from stop bit)
    wait_clks(BIT_CLKS);

    // Frame 2: 0xA5 = 8'b10100101, LSB first: 1,0,1,0,0,1,0,1
    // After 5 bit periods (start + 4 data bits), bit_cnt is in [2,9].
    // Raise m_axis_tready mid-frame to accept 0x3C during Frame 2's data bits.
    rxd = 1'b0; wait_clks(BIT_CLKS);  // start
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[0]
    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[1]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[2]
    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[3]

    // Accept the stalled 0x3C while Frame 2 is mid-data-bit (bit_cnt ~5)
    m_axis_tready = 1'b1;

    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[4]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[5]
    rxd = 1'b0; wait_clks(BIT_CLKS);  // data[6]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // data[7]
    rxd = 1'b1; wait_clks(BIT_CLKS);  // stop

    // m_axis_tvalid rises with 0xA5, no overrun (0x3C already accepted)
    wait_clks(10);
    $finish;
  end

  initial begin
    #100_000;
    $fatal(1, "timeout");
  end

endmodule
